import React from 'react';

import Anchor from '../../partials/anchor';
import CodeBlock from '../../partials/code-block';
import ListItem from '../../partials/list-item';
import Name from '../../partials/name';
import Paragraph from '../../partials/paragraph';
import Header from '../../partials/segment-header';
import NotePad from '../../partials/pad/note';

const provide_at_root_default =
`import { provideContextService } from '@webkrafters/ng-eagleeye';

export const appConfig: ApplicationConfig = {
    providers: [
        provideContextService() 
    ]
};`

const provide_at_root =
`import { provideContextService } from '@webkrafters/ng-eagleeye';

export const appConfig: ApplicationConfig = {
    providers: [
        provideContextService({
            attrs? : {
                prehooks? : Prehooks<T>;
                storage? : IStorage<T>;
                value? : T | AutoImmutable<T>;
            },
            ref? : InjectionToken<ContextService<T>>
        })
    ]
};`

const consume_at_root_default =
`import { CustomService } from '@webkrafters/ng-eagleeye';

@Component()
export class TestComponent{
    myContext = inject( CustomService );
}`

const referenceable_base_context =
`import {
    CONTEXT_DESCRIPTOR,
    provideContextService
} from '@webkrafters/ng-eagleeye';

export const CONTEXT_TOKEN = new InjectionToken( \`\$\{ CONTEXT_DESCRIPTOR \}_Testing\` );

export const appConfig: ApplicationConfig = {
    providers: [
        provideContextService(),
        provideContextService({
            ref: CONTEXT_TOKEN
        })
    ]
};`

const consume_referenceable_base_context =
`import { provideContextSerivce } from @webkrafters/ng-eagleeye;
import { CONTEXT_TOKEN } from './referenceable_base_context;

@Component({
    providers: [ provideContextSerivce() ]
})
export class TestComponent{
    myContext = inject( CustomService );
    sharedContext = inject( CONTEXT_TOKEN );
}`

const OverviewPage : React.FC<{className? : string}> = ({ className }) => (
    <article className={ `overview-page ${ className }` }>
        <h1><Name /> Context Overview</h1>
        <Paragraph><Name /> Context is a streamable context based state management whose state is pluggable. A pluggable state is an instance of the <Anchor to="https://auto-immutable.js.org/intro">AutoImmutableJS</Anchor> class. Multiple systems and applications running any of the <Anchor to="https://eagleeye.org.js">Eagle Eye</Anchor> based <Anchor to="https://www.npmjs.com/package/@webkrafters/eagleeye?activeTab=readme#usage">state management systems</Anchor> can share a single state instance.</Paragraph>
        <Paragraph><Name /> Context Service makes the afore-described context available to Angular systems and applications. This service runs alongside the main program with an express objective to manage state in an easy secure no-frills manner.</Paragraph>
        <h3>Obtaining the Service</h3>
        <Paragraph>
            To access the <Name /> context in Angular environment, a <code>ContextService</code> class has been provided. This service can be provided to the Angular applicatoin environment in two options. Namely:
            <ul>
                <li>at the <b><u>root</u></b> level { "(" }i.e. visible globally within the app{ ")" }.</li>
                <li>at the <b><u>scope</u></b> level { "(" }visible within a specific section of the app.{ ")" }.</li>
            </ul> 
        </Paragraph>
        <h4>Service Configuration</h4>
        <Paragraph>Before we begin with the creation and provision of the service, let us pave the way by acquainting ourselves with the input configuration expected by this service provider.</Paragraph>
        <Paragraph>
            <Header>Configuration Object:</Header>
            <table style={{
                borderCollapse: 'separate',
                borderSpacing: '10px 5px'
            }}>
                <thead>
                    <tr>
                        <th><b>Property</b></th>
                        <th><b>Type</b></th>
                        <th><b>Optional</b></th>
                        <th><b>Description</b></th>
                    </tr>
                </thead>
                <tbody>
                    <tr>
                        <td><b>attrs.prehooks</b></td>
                        <td>Prehooks{ "<" }T{ ">" }</td>
                        <td>Yes</td>
                        <td>Please see <Anchor to="/concepts/prehooks">prehooks</Anchor></td>
                    </tr>
                    <tr>
                        <td><b>attrs.storage</b></td>
                        <td>IStorage{ "<" }T{ ">" }</td>
                        <td>Yes</td>
                        <td>Please see <Anchor to="/concepts/storage">storage</Anchor></td>
                    </tr>
                    <tr>
                        <td><b>attrs.value</b></td>
                        <td>T { "|" } <Anchor to="https://auto-immutable.js.org/intro">AutoImmutable{ "<" }T{ ">" }</Anchor></td>
                        <td>Yes</td>
                        <td>The state object where a state object is a plain object. Also acceptable is an <Anchor to="https://auto-immutable.js.org/intro">AutoImmutable</Anchor> already holding this state object.</td>
                    </tr>
                    <tr>
                        <td><b>ref</b></td>
                        <td>InjectionToken{ "<" }ContextService{ "<" }T{ ">> "}</td>
                        <td>Yes</td>
                        <td>A custom reference handle to this context instance. When none provided, <code>ContextService</code> will be used.</td>
                    </tr>
                </tbody>
            </table>
        </Paragraph>
        <h4>Providing the ContextService at the Root Level</h4>
        <Paragraph>The <code>provideContextService{ "(...)" }</code> creates and provides an instance of the <Name /> context service.</Paragraph>
        <Paragraph>The following is the <b>default</b> case. The state will be initialized with an AutoImmutable instance holding an empty plain object as state object.</Paragraph>
        <CodeBlock>{ provide_at_root_default }</CodeBlock>
        <Paragraph>The follwing is a complete view of a <code>provideContextService{ "(...)" }</code>. Any omitted property is supplied a default equivalent.</Paragraph>
        <CodeBlock>{ provide_at_root }</CodeBlock>
        <h4>Service Referenceabiility</h4>
        <Paragraph>Custom reference handle for provided ContextService instance is generally unnecessary. Contrarily, there are a few cases in which this feature may be used to avoid resource override within the Angular DI system. For instance:</Paragraph>
        <h4>Scenario #1</h4>
        <Paragraph>Let's provide at the application root without a custom ref.</Paragraph>
        <CodeBlock>{ provide_at_root_default }</CodeBlock>
        <Paragraph>Let's consume the provided context service.</Paragraph>
        <CodeBlock>{ consume_at_root_default }</CodeBlock>
        <Header><b><u>Aftermath:</u></b></Header>
        <Paragraph><code>this.myContext</code> will hold the lone <code>CustomService</code> instance provided.</Paragraph>
        <h4>Scenario #2</h4>
        <Paragraph>Let's provide at an application root with and without a custom ref.</Paragraph>
        <CodeBlock>{ referenceable_base_context }</CodeBlock>
        <Paragraph>Let's attemept to consume our provided context services.</Paragraph>
        <CodeBlock>{ consume_referenceable_base_context }</CodeBlock>
        <Header><b><u>Aftermath:</u></b></Header>
        <Paragraph>Ironically, <code>this.myContext</code> will hold the non-custom referenced <code>CustomService</code> instance provided at the <code>TestService</code> scope level. The non-custom referenced <code>CustomService</code> provided at the root level is unreachable.</Paragraph>
        <Paragraph><code>this.sharedContext</code> will hold the custom referenced <code>CustomService</code> from the root provision.</Paragraph>
        <Paragraph>
            <NotePad>
                <Header>Custom Reference Naming Covention</Header>
                <div>The description string acceptable to <code>config.ref</code> to be have the "EagleEye_Context_Service_" prefix.</div>
            </NotePad>
        </Paragraph>
        <Paragraph>
            See example of using the StreamService using a ContextService reference.
        </Paragraph>
        <h4>Intro to Streamability</h4>
        <Paragraph>
            This context service is best when used via its streaming service. Produces automatic signals for its data properties. Changes can be made directly to data properties but those changes do not affect context data. Only the stream API can write into the context.  It removes verbosity...
        </Paragraph>
        <Paragraph>
            <Anchor to="/streaming">See Streaming</Anchor>
        </Paragraph>
        <h4>APIs</h4>
        <Paragraph id="cache">
            <h3>cache</h3>
            <ListItem><div>is a property providing access to the underlying immutable cache managed by this <Name /> instance.</div></ListItem>
        </Paragraph>
        <Paragraph id="closed">
            <h3>closed</h3>
            <ListItem><div>is a boolean property confirming that the context is still active.</div></ListItem>
            <ListItem><div>Use the <CodeBlock isInline>{ `this.contextService.store.subscribe( 'closing', () { "=>" } void )` }</CodeBlock> event to be notified right before this context{ '\`s' } deactivation.</div></ListItem>
            <ListItem><div>Please see the <Anchor to="/overview#dispose">dispose</Anchor> method below.</div></ListItem>
        </Paragraph>
        <Paragraph id="dispose">
            <h3>dispose</h3>
            <ListItem><div>is a context method to deactivates this context.</div></ListItem>
            <ListItem><div>Context deactivation is permanent.</div></ListItem>
            <ListItem><div>The context's <Anchor to="/overview#closed"><code>closed</code></Anchor> property confirms this status.</div></ListItem>
        </Paragraph>
        <hr />
        <Paragraph>
            <Anchor to="/direct-usage">See using this service directly</Anchor>
        </Paragraph>
    </article>
);

export default OverviewPage;
